'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import {
    CreditCard, Banknote, Terminal, Wallet, Gift,
    ArrowLeft, Check, Plus, Trash2, AlertCircle,
    Tag, Percent, DollarSign, ShieldCheck,
    Clock, Package
} from 'lucide-react';
import { usePOS } from '@/modules/pos/context/POSContext';
import { POSTransaction, POSDiscount } from '../types/pos';
import '../styles/pos-rush.css';

const PAYMENT_METHODS = [
    { id: 'cash', label: 'Cash', icon: Banknote, color: '#10B981' },
    { id: 'card', label: 'Card', icon: CreditCard, color: '#3B82F6' },
    { id: 'terminal', label: 'Terminal', icon: Terminal, color: '#8B5CF6' },
    { id: 'wallet', label: 'Wallet', icon: Wallet, color: '#F59E0B' },
    { id: 'gift_card', label: 'Gift Card', icon: Gift, color: '#EC4899' },
];

const MOCK_COUPONS = [
    { id: 'WELCOME20', name: 'Welcome Offer', desc: '20% off on all items', type: 'PERCENTAGE', value: 20, validity: 'Dec 2026', items: 'All Items' },
    { id: 'PIZZA50', name: 'Pizza Party', desc: '$5.00 off on Pizzas', type: 'FIXED', value: 5, validity: 'Nov 2026', items: 'Pizzas' },
    { id: 'BOGO', name: 'Buy 1 Get 1', desc: 'Free classic burger', type: 'PERCENTAGE', value: 100, validity: 'Oct 2026', items: 'Burgers' },
];

export const POSPaymentScreen: React.FC = () => {
    const router = useRouter();
    const searchParams = useSearchParams();
    const {
        cart, cartTotal, discount, setPOSDiscount,
        transactions, setTransactions, setOrderResult,
        session, selectedCustomer
    } = usePOS();

    // Local UI State
    const initialView = searchParams.get('view') === 'discount' ? 'DISCOUNT' : 'METHODS';
    const [view, setView] = useState<'METHODS' | 'DISCOUNT' | 'PROCESSING'>(initialView);
    const [currentMethod, setCurrentMethod] = useState<string | null>(null);
    const [numpadValue, setNumpadValue] = useState<string>('');
    const [activeTab, setActiveTab] = useState<'AMOUNT' | 'TIP'>('AMOUNT');
    const [tipValue, setTipValue] = useState<string>('');
    const [processingStep, setProcessingStep] = useState<'INPUT' | 'WAITING' | 'RESULT'>('INPUT');
    const [error, setError] = useState<string | null>(null);
    const [showManagerPin, setShowManagerPin] = useState(false);
    const [managerPin, setManagerPin] = useState('');

    // Discount local state
    const [manualDiscountType, setManualDiscountType] = useState<'PERCENT' | 'FIXED'>('PERCENT');
    const [manualDiscountValue, setManualDiscountValue] = useState('');
    const [manualDiscountReason, setManualDiscountReason] = useState('');

    // Calculations
    const subtotal = cartTotal;

    const discountAmount = useMemo(() => {
        if (!discount) return 0;
        if (discount.type === 'PERCENTAGE') return (subtotal * discount.value) / 100;
        return discount.value;
    }, [subtotal, discount]);

    const taxAmount = (subtotal - discountAmount) * 0.1; // 10% tax
    const totalDue = Math.max(0, subtotal - discountAmount + taxAmount);

    const amountPaid = transactions
        .filter(t => t.status === 'SUCCESS')
        .reduce((sum, t) => sum + t.amount, 0);

    const remainingBalance = Math.max(0, totalDue - amountPaid);

    // Auto-pre-fill remaining balance when entering payment mode
    useEffect(() => {
        if (currentMethod && remainingBalance > 0 && numpadValue === '') {
            setNumpadValue(remainingBalance.toFixed(2));
        }
    }, [currentMethod, remainingBalance]);

    const handleNumpadClick = (val: string) => {
        setError(null);
        if (val === 'C') {
            if (activeTab === 'AMOUNT') setNumpadValue('');
            else setTipValue('');
            return;
        }

        const current = activeTab === 'AMOUNT' ? numpadValue : tipValue;
        const setter = activeTab === 'AMOUNT' ? setNumpadValue : setTipValue;

        if (val === '.' && current.includes('.')) return;
        setter(current + val);
    };

    const handleApplyManualDiscount = () => {
        const val = parseFloat(manualDiscountValue);
        if (isNaN(val) || val <= 0) {
            setError('Enter valid discount value');
            return;
        }
        if (!manualDiscountReason.trim()) {
            setError('Reason is mandatory for manual discount');
            return;
        }

        // Threshold check (e.g., > 25% or > $50 requires manager approval)
        const isHighDiscount = manualDiscountType === 'PERCENT' ? val > 25 : val > 50;
        if (isHighDiscount) {
            setShowManagerPin(true);
            return;
        }

        applyDiscount();
    };

    const applyDiscount = (coupon?: typeof MOCK_COUPONS[0]) => {
        if (coupon) {
            setPOSDiscount({
                type: coupon.type as any,
                value: coupon.value,
                couponCode: coupon.id
            });
        } else {
            setPOSDiscount({
                type: manualDiscountType === 'PERCENT' ? 'PERCENTAGE' : 'FIXED',
                value: parseFloat(manualDiscountValue),
                reason: manualDiscountReason
            });
        }
        setView('METHODS');
        setError(null);
        // Clear manual inputs
        setManualDiscountValue('');
        setManualDiscountReason('');
    };

    const handleManagerApproval = () => {
        if (managerPin === '1234') { // Mock PIN
            setShowManagerPin(false);
            setManagerPin('');
            applyDiscount();
        } else {
            setError('Invalid Manager PIN');
        }
    };

    const handleProcessPayment = async () => {
        const amount = parseFloat(numpadValue);
        if (isNaN(amount) || amount <= 0) {
            setError('Enter a valid amount');
            return;
        }

        setProcessingStep('WAITING');
        setError(null);

        // Simulate terminal processing
        await new Promise(r => setTimeout(r, 2000));

        // Mock failure for card if amount is 13
        if (currentMethod === 'card' && amount === 13) {
            setError('Transaction Declined: Insufficient Funds');
            setProcessingStep('INPUT');
            return;
        }

        const newTx: POSTransaction = {
            id: Math.random().toString(36).substr(2, 9),
            method: currentMethod as any,
            amount: amount,
            tip: parseFloat(tipValue) || 0,
            status: 'SUCCESS',
            timestamp: new Date()
        };

        const updatedTxs = [...transactions, newTx];
        setTransactions(updatedTxs);

        const newAmountPaid = updatedTxs.reduce((sum, t) => sum + t.amount, 0);

        if (newAmountPaid >= totalDue) {
            // Full payment completion
            const result = {
                orderId: `ORD-${Math.floor(Math.random() * 9000) + 1000}`,
                totalAmount: totalDue,
                paidAmount: newAmountPaid,
                changeDue: Math.max(0, newAmountPaid - totalDue),
                items: cart.length,
                customerName: selectedCustomer?.name,
                fulfillment: session?.channel || 'Dine-In',
                eta: '20 mins'
            };
            setOrderResult(result);
            router.push('/pos/confirmation');
        } else {
            // Partial payment
            setCurrentMethod(null);
            setView('METHODS');
            setProcessingStep('INPUT');
            setNumpadValue('');
            setTipValue('');
        }
    };

    const removeTransaction = (id: string) => {
        setTransactions(prev => prev.filter(tx => tx.id !== id));
    };

    return (
        <div className="pos-screen" style={{ display: 'flex', background: 'var(--pos-bg-surface)', height: '100vh', overflow: 'hidden' }}>
            {/* Left Section: Main Flow */}
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', borderRight: '1px solid var(--pos-border-subtle)' }}>
                {/* Header */}
                <header style={{ height: '92px', padding: '0 32px', borderBottom: '1px solid var(--pos-border-subtle)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: 'var(--pos-bg-card)' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
                        <button
                            onClick={() => view === 'METHODS' ? router.back() : setView('METHODS')}
                            style={{ width: '48px', height: '48px', borderRadius: '14px', background: 'var(--pos-bg-surface)', border: '1px solid var(--pos-border-subtle)', color: 'var(--pos-text-primary)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                        >
                            <ArrowLeft size={24} />
                        </button>
                        <div>
                            <h2 style={{ fontSize: '24px', fontWeight: 900, color: 'var(--pos-text-primary)' }}>
                                {view === 'METHODS' && 'Payment Selection'}
                                {view === 'DISCOUNT' && 'Offers & Discounts'}
                                {view === 'PROCESSING' && `Processing ${currentMethod?.toUpperCase()}`}
                            </h2>
                            <p style={{ fontSize: '12px', fontWeight: 700, color: 'var(--pos-text-muted)', textTransform: 'uppercase', letterSpacing: '0.1em' }}>
                                Order #{selectedCustomer?.id || 'WALK-IN'}
                            </p>
                        </div>
                    </div>

                    {view === 'METHODS' && !discount && (
                        <button
                            onClick={() => setView('DISCOUNT')}
                            style={{ height: '52px', padding: '0 24px', borderRadius: '14px', background: 'rgba(245, 158, 11, 0.1)', border: '1px solid rgba(245, 158, 11, 0.2)', color: '#F59E0B', fontWeight: 900, fontSize: '14px', display: 'flex', alignItems: 'center', gap: '10px' }}
                        >
                            <Tag size={18} /> APPLY DISCOUNT
                        </button>
                    )}
                </header>

                <main style={{ flex: 1, padding: '32px', overflowY: 'auto' }}>
                    {view === 'METHODS' && !currentMethod && (
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '24px', maxWidth: '800px', margin: '0 auto' }}>
                            {PAYMENT_METHODS.map(m => (
                                <button
                                    key={m.id}
                                    onClick={() => {
                                        setCurrentMethod(m.id);
                                        setView('PROCESSING');
                                    }}
                                    className="hover-scale"
                                    style={{ height: '160px', borderRadius: '28px', background: 'var(--pos-bg-card)', border: '1px solid var(--pos-border-subtle)', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '16px' }}
                                >
                                    <div style={{ width: '64px', height: '64px', borderRadius: '20px', background: `${m.color}15`, color: m.color, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                        <m.icon size={36} />
                                    </div>
                                    <span style={{ fontSize: '20px', fontWeight: 900, color: 'var(--pos-text-primary)', textTransform: 'uppercase' }}>{m.label}</span>
                                </button>
                            ))}
                        </div>
                    )}

                    {view === 'DISCOUNT' && (
                        <div style={{ display: 'flex', gap: '32px', height: '100%' }}>
                            {/* Coupons List */}
                            <div style={{ flex: 1.5 }}>
                                <h3 style={{ fontSize: '18px', fontWeight: 900, marginBottom: '24px', display: 'flex', alignItems: 'center', gap: '10px' }}>
                                    <ShieldCheck size={20} color="var(--pos-action-primary)" /> ACTIVE COUPONS
                                </h3>
                                <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                                    {MOCK_COUPONS.map(c => (
                                        <div key={c.id} style={{ padding: '24px', background: 'var(--pos-bg-card)', borderRadius: '24px', border: '1px solid var(--pos-border-subtle)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                            <div>
                                                <div style={{ fontSize: '18px', fontWeight: 900, color: 'var(--pos-text-primary)', marginBottom: '4px' }}>{c.name}</div>
                                                <div style={{ fontSize: '13px', color: 'var(--pos-text-muted)', marginBottom: '8px', fontWeight: 600 }}>{c.desc}</div>
                                                <div style={{ display: 'flex', gap: '12px' }}>
                                                    <span style={{ fontSize: '11px', fontWeight: 800, background: 'var(--pos-bg-surface)', padding: '4px 10px', borderRadius: '6px', color: 'var(--pos-text-secondary)' }}>{c.validity}</span>
                                                    <span style={{ fontSize: '11px', fontWeight: 800, background: 'rgba(31, 164, 169, 0.1)', padding: '4px 10px', borderRadius: '6px', color: 'var(--pos-action-primary)' }}>{c.items}</span>
                                                </div>
                                            </div>
                                            <button
                                                onClick={() => applyDiscount(c)}
                                                className="pos-btn-primary"
                                                style={{ height: '48px', padding: '0 24px', borderRadius: '12px' }}
                                            >APPLY</button>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Manual Discount Entry */}
                            <div style={{ flex: 1, padding: '32px', background: 'var(--pos-bg-surface)', borderRadius: '32px', border: '1px solid var(--pos-border-subtle)' }}>
                                <h3 style={{ fontSize: '18px', fontWeight: 900, marginBottom: '24px', color: 'var(--pos-text-primary)' }}>MANUAL ADJUSTMENT</h3>

                                <div style={{ display: 'flex', background: 'var(--pos-bg-card)', borderRadius: '16px', padding: '6px', marginBottom: '24px', border: '1px solid var(--pos-border-subtle)' }}>
                                    <button
                                        onClick={() => setManualDiscountType('PERCENT')}
                                        style={{ flex: 1, height: '44px', borderRadius: '12px', background: manualDiscountType === 'PERCENT' ? 'var(--pos-action-primary)' : 'transparent', color: manualDiscountType === 'PERCENT' ? 'white' : 'var(--pos-text-muted)', border: 'none', fontWeight: 800 }}
                                    ><Percent size={18} /></button>
                                    <button
                                        onClick={() => setManualDiscountType('FIXED')}
                                        style={{ flex: 1, height: '44px', borderRadius: '12px', background: manualDiscountType === 'FIXED' ? 'var(--pos-action-primary)' : 'transparent', color: manualDiscountType === 'FIXED' ? 'white' : 'var(--pos-text-muted)', border: 'none', fontWeight: 800 }}
                                    ><DollarSign size={18} /></button>
                                </div>

                                <div style={{ marginBottom: '24px' }}>
                                    <label style={{ fontSize: '12px', fontWeight: 900, color: 'var(--pos-text-muted)', textTransform: 'uppercase', marginBottom: '8px', display: 'block' }}>Discount Value</label>
                                    <input
                                        type="number"
                                        placeholder="0.00"
                                        value={manualDiscountValue}
                                        onChange={(e) => setManualDiscountValue(e.target.value)}
                                        className="pos-input"
                                        style={{ height: '64px', fontSize: '24px', fontWeight: 900 }}
                                    />
                                </div>

                                <div style={{ marginBottom: '32px' }}>
                                    <label style={{ fontSize: '12px', fontWeight: 900, color: 'var(--pos-text-muted)', textTransform: 'uppercase', marginBottom: '8px', display: 'block' }}>Reason for discount</label>
                                    <textarea
                                        placeholder="e.g. Employee Meal, Service Delay"
                                        value={manualDiscountReason}
                                        onChange={(e) => setManualDiscountReason(e.target.value)}
                                        className="pos-input"
                                        style={{ height: '100px', padding: '16px', resize: 'none' }}
                                    />
                                </div>

                                {error && (
                                    <div style={{ color: '#EF4444', fontSize: '13px', fontWeight: 700, marginBottom: '20px', textAlign: 'center' }}>{error}</div>
                                )}

                                <button
                                    onClick={handleApplyManualDiscount}
                                    className="pos-btn-primary"
                                    style={{ width: '100%', height: '64px', borderRadius: '18px' }}
                                >APPLY ON ORDER</button>
                            </div>
                        </div>
                    )}

                    {view === 'PROCESSING' && (
                        <div style={{ maxWidth: '480px', margin: '0 auto', height: '100%', display: 'flex', flexDirection: 'column' }}>
                            {processingStep === 'WAITING' ? (
                                <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '32px' }}>
                                    <div style={{ width: '100px', height: '100px', borderRadius: '50%', border: '8px solid rgba(31, 164, 169, 0.1)', borderTopColor: 'var(--pos-action-primary)', animation: 'spin 1s linear infinite' }} />
                                    <div style={{ textAlign: 'center' }}>
                                        <h3 style={{ fontSize: '28px', fontWeight: 900, color: 'white', marginBottom: '8px' }}>Waiting for Terminal...</h3>
                                        <p style={{ color: 'var(--pos-text-muted)', fontWeight: 600 }}>Please follow the instructions on terminal</p>
                                    </div>
                                </div>
                            ) : (
                                <div style={{ display: 'flex', flexDirection: 'column', gap: '32px' }}>
                                    {/* Amount Display */}
                                    <div style={{ display: 'flex', borderRadius: '24px', overflow: 'hidden', border: '1px solid var(--pos-border-subtle)', height: '100px', background: 'var(--pos-bg-card)' }}>
                                        <button
                                            onClick={() => setActiveTab('AMOUNT')}
                                            style={{ flex: 1.5, background: activeTab === 'AMOUNT' ? 'rgba(31, 164, 169, 0.1)' : 'transparent', border: 'none', textAlign: 'left', padding: '0 24px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}
                                        >
                                            <span style={{ fontSize: '11px', fontWeight: 900, color: 'var(--pos-text-muted)', textTransform: 'uppercase', marginBottom: '4px' }}>Total to Charge</span>
                                            <span style={{ fontSize: '32px', fontWeight: 900, color: activeTab === 'AMOUNT' ? 'var(--pos-action-primary)' : 'white' }}>${numpadValue || '0.00'}</span>
                                        </button>
                                        <button
                                            onClick={() => setActiveTab('TIP')}
                                            style={{ flex: 1, background: activeTab === 'TIP' ? 'rgba(31, 164, 169, 0.1)' : 'transparent', border: 'none', borderLeft: '1px solid var(--pos-border-subtle)', textAlign: 'left', padding: '0 24px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}
                                        >
                                            <span style={{ fontSize: '11px', fontWeight: 900, color: 'var(--pos-text-muted)', textTransform: 'uppercase', marginBottom: '4px' }}>Add Tip</span>
                                            <span style={{ fontSize: '24px', fontWeight: 900, color: activeTab === 'TIP' ? 'var(--pos-action-primary)' : 'var(--pos-text-muted)' }}>${tipValue || '0.00'}</span>
                                        </button>
                                    </div>

                                    {/* Numpad */}
                                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '16px' }}>
                                        {[1, 2, 3, 4, 5, 6, 7, 8, 9, '.', 0, 'C'].map(btn => (
                                            <button
                                                key={btn}
                                                onClick={() => handleNumpadClick(btn.toString())}
                                                style={{ height: '80px', borderRadius: '20px', background: 'var(--pos-bg-card)', border: '1px solid var(--pos-border-subtle)', color: 'white', fontSize: '28px', fontWeight: 900 }}
                                            >{btn}</button>
                                        ))}
                                    </div>

                                    {error && (
                                        <div style={{ padding: '16px', background: 'rgba(239, 68, 68, 0.1)', border: '1px solid rgba(239, 68, 68, 0.2)', borderRadius: '16px', color: '#EF4444', fontSize: '14px', fontWeight: 700, display: 'flex', alignItems: 'center', gap: '12px' }}>
                                            <AlertCircle size={20} /> {error}
                                        </div>
                                    )}

                                    <div style={{ display: 'flex', gap: '16px' }}>
                                        <button
                                            onClick={() => { setCurrentMethod(null); setView('METHODS'); }}
                                            className="pos-btn-secondary" style={{ flex: 1, height: '72px', borderRadius: '20px' }}
                                        >CANCEL</button>
                                        <button
                                            onClick={handleProcessPayment}
                                            className="pos-btn-primary" style={{ flex: 2, height: '72px', borderRadius: '20px', fontSize: '18px' }}
                                        >CONFIRM PAYMENT</button>
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </main>
            </div>

            {/* Right Section: Order Summary */}
            <aside style={{ width: '440px', background: 'var(--pos-bg-card)', display: 'flex', flexDirection: 'column' }}>
                <div style={{ padding: '32px', borderBottom: '1px solid var(--pos-border-subtle)' }}>
                    <h3 style={{ fontSize: '12px', fontWeight: 900, color: 'var(--pos-text-muted)', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '24px', textAlign: 'center' }}>Checkout Summary</h3>

                    <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '15px', fontWeight: 700 }}>
                            <span style={{ color: 'var(--pos-text-muted)' }}>Subtotal</span>
                            <span style={{ color: 'white' }}>${subtotal.toFixed(2)}</span>
                        </div>

                        {discount && (
                            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '15px', fontWeight: 800 }}>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#F59E0B' }}>
                                    <Tag size={16} />
                                    <span>Discount {discount.couponCode ? `(${discount.couponCode})` : ''}</span>
                                    <button onClick={() => setPOSDiscount(null)} style={{ background: 'transparent', border: 'none', color: '#EF4444', cursor: 'pointer', display: 'flex' }}><Trash2 size={14} /></button>
                                </div>
                                <span style={{ color: '#F59E0B' }}>-${discountAmount.toFixed(2)}</span>
                            </div>
                        )}

                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '15px', fontWeight: 700 }}>
                            <span style={{ color: 'var(--pos-text-muted)' }}>Tax (GST 10%)</span>
                            <span style={{ color: 'white' }}>${taxAmount.toFixed(2)}</span>
                        </div>

                        <div style={{ margin: '8px 0', borderTop: '2px dashed var(--pos-border-subtle)' }} />

                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>
                            <span style={{ fontSize: '14px', fontWeight: 900, color: 'white', textTransform: 'uppercase' }}>Amount Due</span>
                            <span style={{ fontSize: '42px', fontWeight: 900, color: 'white', letterSpacing: '-0.02em', lineHeight: 1 }}>${totalDue.toFixed(2)}</span>
                        </div>
                    </div>
                </div>

                <div style={{ flex: 1, padding: '32px', display: 'flex', flexDirection: 'column', gap: '24px' }}>
                    {/* Payment Indicators */}
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                        <div style={{ padding: '16px', background: 'var(--pos-bg-surface)', borderRadius: '16px', border: '1px solid var(--pos-border-subtle)', textAlign: 'center' }}>
                            <div style={{ fontSize: '10px', fontWeight: 800, color: 'var(--pos-text-muted)', textTransform: 'uppercase', marginBottom: '4px' }}>Paid Amount</div>
                            <div style={{ fontSize: '18px', fontWeight: 900, color: '#10B981' }}>${amountPaid.toFixed(2)}</div>
                        </div>
                        <div style={{ padding: '16px', background: 'var(--pos-bg-surface)', borderRadius: '16px', border: '1px solid var(--pos-border-subtle)', textAlign: 'center' }}>
                            <div style={{ fontSize: '10px', fontWeight: 800, color: 'var(--pos-text-muted)', textTransform: 'uppercase', marginBottom: '4px' }}>Remaining</div>
                            <div style={{ fontSize: '18px', fontWeight: 900, color: remainingBalance > 0 ? '#F59E0B' : 'var(--pos-text-muted)' }}>${remainingBalance.toFixed(2)}</div>
                        </div>
                    </div>

                    {/* Transactions List */}
                    <div style={{ flex: 1, overflowY: 'auto' }}>
                        <h4 style={{ fontSize: '11px', fontWeight: 900, color: 'var(--pos-text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '16px' }}>Applied Transactions</h4>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                            {transactions.length === 0 ? (
                                <div style={{ border: '2px dashed var(--pos-border-subtle)', borderRadius: '20px', padding: '32px', textAlign: 'center', color: 'var(--pos-text-muted)', fontSize: '13px', fontWeight: 600 }}>
                                    Waiting for first payment...
                                </div>
                            ) : (
                                transactions.map(t => (
                                    <div key={t.id} style={{ padding: '16px', background: 'var(--pos-bg-surface)', borderRadius: '16px', border: '1px solid var(--pos-border-subtle)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                            <div style={{ width: '32px', height: '32px', borderRadius: '8px', background: 'rgba(16, 185, 129, 0.1)', color: '#10B981', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                                <Check size={16} strokeWidth={3} />
                                            </div>
                                            <div>
                                                <div style={{ fontSize: '14px', fontWeight: 900, textTransform: 'uppercase' }}>{t.method}</div>
                                                {t.tip > 0 && <div style={{ fontSize: '11px', color: 'var(--pos-text-muted)', fontWeight: 600 }}>Tip: ${t.tip.toFixed(2)}</div>}
                                            </div>
                                        </div>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                            <span style={{ fontSize: '16px', fontWeight: 900 }}>${t.amount.toFixed(2)}</span>
                                            <button onClick={() => removeTransaction(t.id)} style={{ border: 'none', background: 'transparent', color: '#EF4444', cursor: 'pointer', padding: '4px' }}><Trash2 size={16} /></button>
                                        </div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>

                    <button
                        disabled={remainingBalance > 0}
                        onClick={() => {/* Finalize step - though processed in handleProcessPayment automatically */ }}
                        className="pos-btn-primary"
                        style={{ height: '72px', borderRadius: '20px', fontSize: '18px', display: remainingBalance > 0 ? 'none' : 'flex' }}
                    >
                        COMPLETE ORDER
                    </button>
                </div>
            </aside>

            {/* Manager PIN Modal */}
            {showManagerPin && (
                <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)', backdropFilter: 'blur(10px)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    <div style={{ width: '360px', background: 'var(--pos-bg-card)', borderRadius: '32px', padding: '40px', textAlign: 'center', border: '1px solid var(--pos-border-subtle)' }}>
                        <ShieldCheck size={48} color="#F59E0B" style={{ marginBottom: '24px' }} />
                        <h3 style={{ fontSize: '22px', fontWeight: 900, marginBottom: '8px' }}>Manager Approval</h3>
                        <p style={{ color: 'var(--pos-text-muted)', fontSize: '14px', marginBottom: '32px' }}>High discount threshold exceeded. Please enter authorizing PIN.</p>

                        <input
                            type="password"
                            maxLength={4}
                            value={managerPin}
                            onChange={(e) => setManagerPin(e.target.value)}
                            placeholder="****"
                            style={{ width: '100%', height: '80px', background: 'var(--pos-bg-surface)', border: '1px solid var(--pos-border-subtle)', borderRadius: '20px', textAlign: 'center', fontSize: '32px', letterSpacing: '0.4em', fontWeight: 900, color: 'white', marginBottom: '32px' }}
                        />

                        <div style={{ display: 'flex', gap: '12px' }}>
                            <button onClick={() => setShowManagerPin(false)} className="pos-btn-secondary" style={{ flex: 1, height: '60px', borderRadius: '16px' }}>CANCEL</button>
                            <button onClick={handleManagerApproval} className="pos-btn-primary" style={{ flex: 1, height: '60px', borderRadius: '16px' }}>APPROVE</button>
                        </div>
                    </div>
                </div>
            )}

            <style>{`
                @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
                .pos-input:focus { border-color: var(--pos-action-primary); outline: none; box-shadow: 0 0 0 4px rgba(31, 164, 169, 0.1); }
            `}</style>
        </div>
    );
};

export default POSPaymentScreen;
